sp_widget.client_script:
$scope.attachments = {};

$scope.uploadFile = function(file, docType) {
  spAttachmentAPI.attachFileToRecord(file, 'x_1811084_diya_c_0_customer_profile', null).then(function(response) {
    $scope.attachments[docType] = response.sys_id;
    console.log(docType + ' uploaded: ' + response.sys_id);
  });
};

$scope.submit = function() {
  var payload = {
    first_name: $scope.data.first_name,
    last_name: $scope.data.last_name,
    user_id: $scope.data.user_id,
    address: $scope.data.address,
    state: $scope.data.state,
    city: $scope.data.city,
    phone: $scope.data.phone,
    aadhaar: $scope.data.aadhaar,
    pan: $scope.data.pan,
    license: $scope.data.license,
    license_start: $scope.data.license_start,
    license_expiry: $scope.data.license_expiry,
    attachments: $scope.attachments
  };

  $scope.server.get(payload).then(function(response) {
    alert("User registered successfully.");
    $scope.data = {}; // clear form
    $scope.attachments = {};
  });
};

sp_widget.script:
(function() {
  if (!input) return;

  var rec = new GlideRecord('x_1811084_diya_c_0_customer_profile');
  rec.initialize();
  rec.firstname = input.first_name;
  rec.lastname = input.last_name;
  rec.user_id = input.user_id;
  rec.address = input.address;
  rec.state = input.state;
  rec.city = input.city;
  rec.phone = input.phone;
  rec.u_aadhaar = input.aadhaar;
  rec.u_pan = input.pan;
  rec.u_driving_license = input.license;
  rec.u_start_date = input.license_start;
  rec.u_expiry_date = input.license_expiry;
  var recordSysId = rec.insert();

  // Attach uploaded files to this record
  if (input.attachments) {
    var gsa = new GlideSysAttachment();
    for (var key in input.attachments) {
      var tempSysId = input.attachments[key];
      gsa.copy('sys_attachment', tempSysId, 'x_1811084_diya_c_0_customer_profile', recordSysId);
    }
  }
})();
